#!/usr/bin/env python3
import hashlib,json,struct
from pathlib import Path
R=Path(__file__).resolve().parents[1];D=R/'docs/research'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 out=D/'dedup-joint-opposite-sampling-audit-20261011.json';assert not out.exists();rp=D/'dedup-joint-opposite-sampling-20261011.json';r=json.loads(rp.read_text());assert r['status']=='complete_bounded_high_trial_joint_file_support' and r['returncode']==0;assert all(sha(p)==h for p,h in r['pins'].items());assert sha(r['log'])==r['log_sha256'];assert Path(r['log']).read_text()==r['stdout']+r['stderr'];v=json.loads(r['stdout']);mp=D/'dedup-joint-opposite-sampling-harness-20261011.json';m=json.loads(mp.read_text());assert all(sha(Path(m['harness'])/f)==h for f,h in m['files'].items());gp=D/'dedup-joint-geometry-sampling-patched-20261011.json';g=json.loads(gp.read_text());assert all(sha(p)==h for p,h in g['pins'].items());plan,row=next((p,x) for p,x in zip(g['plan'],g['results']) if p['case']=='207700_opposite_1m');inp=json.loads(Path(plan['input']).read_text());reference=json.loads(row['stdout']);assert len(v['points'])==107==len(inp['points']);assert v['transform']==reference['best']['transform'] and v['pixels']==reference['anchor_result'];assert v['attempted_recipes']==1 and not v['reflected_proposal_source'];assert v['source_tolerance trials']==.5 and v['target_tolerance']==2 and v['managed_used']==0;assert r['command'][-1]=='1000000'
 for original,actual in zip(inp['points'],v['points']):
  for key in ['source','target']:
   assert actual[key]==[struct.unpack('>d',struct.pack('>Q',b))[0] for b in original[key+'_bits']]
 pixels=v['pixels'];assert pixels['supported'] is True and pixels['anchors']==[10,11]
 for d in pixels['directions']:assert d['informative_pairs']>=1000 and d['valid_sites']/d['sites']>=.3 and d['agreeing_pairs']/d['informative_pairs']>=.9
 generic=D/'dedup-joint-sampling-regression-audit-20261011.json';t=json.loads(generic.read_text());assert t['status']=='complete_bounded_frozen_joint_sampling_4_tests' and t['tests']==4;assert all(sha(p)==h for p,h in t['pins'].items());pins={str(p):sha(p) for p in [rp,mp,gp,generic,Path(r['log']),Path(__file__)]};out.write_text(json.dumps({'status':'verified_high_trial_207700_file_recovery','pins':pins,'points':107,'anchors':[10,11],'recipes':1,'diagnostic_field_note':'Frozen probe emitted source_tolerance under misspelled source_tolerance trials key. Value verified; root probe spelling corrected after run. No math/source threshold change.','elapsed_seconds':r['elapsed_seconds'],'scope':'Real file extraction yields same107 actual points and exactly same transform/pixels as independently audited1m-trial exact-bit geometry experiment. Source.5/target2 unchanged; four generic geometry regressions pass. Explicit larger work/projection admission, no default change or high-trial combined primary/collection runtime yet.'},indent=2)+'\n');print('207700 file recovery verified,10/11 anchors')
if __name__=='__main__':main()
